import test from 'node:test';import assert from 'node:assert/strict';import {OnlineRooms} from './scenario-adventure/online-rooms.mjs';
const inventory={allowedIds:['patch-update','firewall-guard','energy-boost']},setup={characterId:'milo',cardIds:['patch-update','firewall-guard','energy-boost','patch-update','firewall-guard']};
for(const count of [2,4])test(`surrender at ${count} seats is authoritative, no invented scores, stale retry blocked and replay resets`,async()=>{const service=new OnlineRooms({random:()=>0}),users=Array.from({length:count},(_,i)=>({id:'surrender-'+i})),created=service.create(users[0],{...setup,maxPlayers:count},inventory),code=created.code;for(const u of users.slice(1))service.join(u,code,setup,inventory);const room=service.get(code,users[0].id);const act=(u,type,extra={})=>service.act(u,code,{revision:room.revision,type,...extra});for(const u of users)await act(u,'ready',{ready:true});await act(users[0],'start');const before=structuredClone(room.match.scores),rev=room.revision,role=service.view(room,users[1].id).role;assert.notEqual(role,room.match.currentTurn);await act(users[1],'surrender',{role:'player',winner:'player',rp:999});assert.equal(room.match.surrenderedBy,role);assert.equal(room.match.endReason,'SURRENDER');assert.equal(room.status,'FINISHED');assert.deepEqual(room.match.scores,before);assert.equal(room.match.responseHistory.length,0);assert.equal(room.match.winners.length,count-1);assert.ok(!room.match.winners.includes(role));await assert.rejects(service.act(users[1],code,{revision:rev,type:'surrender'}),/STALE/);await assert.rejects(act(users[1],'surrender'),/INVALID_PHASE/);for(const u of users)await act(u,'ready',{ready:true});await act(users[0],'start');assert.equal(room.match.endReason,undefined);assert.equal(room.match.surrenderedBy,undefined);assert.equal(room.match.eventHistory.length,0);});
test('nonmember cannot surrender another room',async()=>{const service=new OnlineRooms(),host={id:'host'},created=service.create(host,setup,inventory);await assert.rejects(service.act({id:'stranger'},created.code,{type:'surrender',revision:created.revision}),/ROOM_NOT_FOUND/);});
